def get_api_key():
    try:
        return st.secrets['OPENROUTER_API_KEY']
    except Exception:
        return None

def call_openrouter(messages):
    api_key = get_api_key()
    if not api_key:
        return 'API key belum tersedia. Pastikan OPENROUTER_API_KEY sudah diisi di Streamlit Secrets.'
    headers = {'Authorization': 'Bearer ' + str(api_key), 'Content-Type': 'application/json', 'X-Title': 'FinAI'}
    payload = {'model': MODEL_PRIMARY, 'messages': messages, 'temperature': 0.2, 'max_tokens': 700}
    try:
        response = requests.post('https://openrouter.ai/api/v1/chat/completions', headers=headers, json=payload, timeout=45)
    except Exception as exc:
        return f'Koneksi ke LLM gagal: {type(exc).__name__}.'
    if response.status_code == 429:
        payload['model'] = MODEL_FALLBACK
        try:
            response = requests.post('https://openrouter.ai/api/v1/chat/completions', headers=headers, json=payload, timeout=45)
        except Exception as exc:
            return f'Koneksi ke LLM gagal saat fallback: {type(exc).__name__}.'
    if response.status_code >= 400:
        try:
            err = response.json().get('error', {})
            message = err.get('message', response.text)
        except Exception:
            message = response.text
        return f'LLM API error {response.status_code}: {message}'
    try:
        return response.json()['choices'][0]['message']['content'].strip()
    except Exception:
        return 'LLM mengembalikan respons yang tidak dapat dibaca.'
if 'finai_messages' not in st.session_state:
    st.session_state.finai_messages = [{'role': 'assistant', 'content': "Hi there! 👋\nI'm your Financial AI Assistant.\nHow can I help you today?", 'html': '<b>Hi there! 👋</b><br><span class="muted">I\'m your Financial AI Assistant.<br>How can I help you today?</span>'}, {'role': 'user', 'content': 'Hello'}, {'role': 'assistant', 'content': 'Do you want to compare the current performance with the previous month?'}, {'role': 'user', 'content': 'Yes, compare it with the previous month'}, {'role': 'assistant', 'content': "You spent 699.1 net profit this month versus 812.4 previous month. That's a 13.94% decrease compared to the previous month.", 'html': "You spent <b>699.1 net profit</b> this month versus <b>812.4</b> previous month. That's a <b>13.94% decrease</b> compared to the previous month."}]
component = st.components.v2.component(name='finai_overlay_v1_llm', html=HTML, css=CSS, js=JS, isolate_styles=False)
result = component(data={'messages': st.session_state.finai_messages, 'request_id': st.session_state.get('finai_last_request_id')}, on_submit_change=lambda: None)
if getattr(result, 'submit', None):
    event = result.submit
    if isinstance(event, dict):
        user_text = str(event.get('message', '')).strip()
        request_id = event.get('request_id')
    else:
        user_text = str(event).strip()
        request_id = None
    if user_text:
        st.session_state.finai_messages.append({'role': 'user', 'content': user_text})
        llm_messages = [{'role': 'system', 'content': SYSTEM_PROMPT + '\n\nDASHBOARD CONTEXT:\n' + DASHBOARD_CONTEXT}]
        for msg in st.session_state.finai_messages[-12:]:
            llm_messages.append({'role': msg['role'], 'content': msg['content']})
        answer = call_openrouter(llm_messages)
        st.session_state.finai_messages.append({'role': 'assistant', 'content': answer})
        st.session_state.finai_last_request_id = request_id or str(len(st.session_state.finai_messages))
        st.rerun()
